// ┌─ THIS FILE IS REGENERATED BY THE PRODUCTION BUILD ────────────────────────────────────────────┐
// │ The JordanSoft books deployment overwrites this file wholesale during its web image build      │
// │ (a `printf` in the web stage of that deployment's docker-compose.yml, which lives in a          │
// │ SEPARATE repo). The generated version sets production: true, the real apiBaseUrl and            │
// │ devClientId, and points BOTH devClerk and devApprover at the single owner identity.             │
// │                                                                                                 │
// │ Consequences, both easy to get wrong:                                                           │
// │  • devClerk/devApprover are NOT dead code, even though no production code path reads them —     │
// │    the generator emits them. Deleting them here silently desynchronises the two repos.          │
// │  • Any field added or renamed here must be mirrored in that generator, or the deployed bundle   │
// │    ships without it and fails at RUNTIME, in live books, rather than at build time in CI.       │
// │                                                                                                 │
// │ ./dev-identities.ts is regenerated by the same build. Change either one, check both.            │
// └─────────────────────────────────────────────────────────────────────────────────────────────────┘
export interface DevIdentityConfig { sub: string; name: string; claims: { type: string; value: string }[]; }

export const environment = {
  production: false,
  apiBaseUrl: 'http://localhost:5000',
  // Two dev identities so maker-checker (author ≠ approver) is exercisable in one browser.
  // Both must map to a control-DB membership for the demo client to get real data (not a build/test dependency).
  //
  // These are NOT the roster the app switches between — that is ./dev-identities.ts, which is what
  // DevIdentityService and the auth interceptor read. These two survive as fixtures that specs use for
  // their well-known subs, and because the production generator emits them (see the file header). The
  // names here have drifted from the roster's (…0001 is 'Dev Controller' there); only .sub is relied on.
  devClerk: {
    sub: '00000000-0000-0000-0000-000000000001',
    name: 'Dev Clerk',
    claims: [{ type: 'role', value: 'Controller' }],
  } as DevIdentityConfig,
  devApprover: {
    sub: '00000000-0000-0000-0000-000000000002',
    name: 'Dev Approver',
    claims: [{ type: 'role', value: 'Approver' }, { type: 'admin', value: 'true' }],
  } as DevIdentityConfig,
  devClientId: '' as string, // set to the seeded demo client's Guid before demoing
};
